function getDomoaiTranslation(key, lang) {
    if (domoaiTranslations[lang] && domoaiTranslations[lang][key]) {
        return domoaiTranslations[lang][key];
    }
    if (domoaiTranslations.en && domoaiTranslations.en[key]) {
        return domoaiTranslations.en[key];
    }
    return null;
}

function applyDomoaiTranslations(lang) {
    console.log('Applying domo-ai translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.domo-ai.')) {
            const translation = getDomoaiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} domo-ai translations`);
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyDomoaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyDomoaiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyDomoaiTranslations(currentLang);
}

console.log('domo-ai i18n loaded');
